    "agencybench": (agency_vulnerable_reward, agency_hardened_reward),
    "aidanbench": (aidan_vulnerable_reward, aidan_hardened_reward),
    "structured_outputs": (structured_vulnerable_reward, structured_hardened_reward),
}


